PROGRAM ST290_LIMNINGSCELL
VAR
    steg     : INT := 0;
    xStart   : BOOL := FALSE;
    xValv    : BOOL := FALSE;
    xTrig    : BOOL := FALSE;
    xLid     : BOOL := FALSE;
    xSpann   : BOOL := FALSE;
    xOppen   : BOOL := FALSE;
    xStopp   : BOOL := FALSE;
    tmrDos   : TON;
    tmrOppen : TON;
END_VAR

(* EMG_OK och AIR_OK lases bara. Logiken forreglas AV nodstoppskretsen och
   tryckluftsvakten; den bar ingen sakerhetsfunktion sjalv. *)

(* Doseringen 8,0 s, och ventilen stangs aven pa robotprogrammets egna
   klarbesked ST290_RB_DONE. Oppentiden 180,0 s borjar nar doseringsventilen
   STANGS, alltsa nar ST290_ADH_VALVE gar lag, och aldrig nar programmet
   startar: en strang som tar langre tid ar fortfarande limmets egen klocka. *)
tmrDos(IN := xValv, PT := T#8000ms);
tmrOppen(IN := xOppen, PT := T#180000ms);

IF NOT EMG_OK OR NOT AIR_OK THEN
    xStart := FALSE;
    xValv := FALSE;
    xTrig := FALSE;
    xLid := FALSE;
    xSpann := FALSE;
    xOppen := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            IF (ST290_ADH_TEMP >= 150.0) AND (ST290_ADH_TEMP <= 190.0)
                    AND NOT xStopp THEN
                steg := 1;
            ELSIF ST290_ADH_TEMP > 190.0 THEN
                (* Overhettat lim skinnar snabbare och oppentiden galler
                   inte langre: stationen stoppas. *)
                xStopp := TRUE;
                steg := 9;
            END_IF;
        1:
            xStart := TRUE;
            xValv := TRUE;
            steg := 2;
        2:
            IF tmrDos.Q OR ST290_RB_DONE THEN
                xValv := FALSE;
                xOppen := TRUE;
                xStart := FALSE;
                xTrig := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST290_CAM_LEN > 0.0 THEN
                xTrig := FALSE;
                IF (ST290_CAM_LEN >= 620.0) AND (ST290_CAM_LEN <= 660.0) THEN
                    xLid := TRUE;
                    steg := 4;
                ELSE
                    (* Brott i strangen eller dubbeldosering: locket laggs
                       aldrig pa och enheten lamnas oppen. *)
                    xStopp := TRUE;
                    steg := 9;
                END_IF;
            END_IF;
        4:
            xSpann := TRUE;
            steg := 5;
        5:
            IF ST290_CLP_CLOSED AND NOT tmrOppen.Q THEN
                steg := 6;
            ELSIF tmrOppen.Q THEN
                (* Oppentiden gatt ut: enheten kasseras och fogningen
                   fullfoljs aldrig. *)
                xSpann := FALSE;
                xLid := FALSE;
                xStopp := TRUE;
                steg := 9;
            END_IF;
        6:
            (* Fogad och spand inom oppentiden. *)
            xTrig := FALSE;
        9:
            (* Last til manuell atgard. *)
            xValv := FALSE;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* En skrivning per utgang, forreglingarna i samma uttryck (F7): ventilen
   bara inom temperaturfonstret, locket bara pa en hel strang inom
   langdfonstret, spannaren bara efter locket. *)
ST290_ADH_VALVE := xValv AND (ST290_ADH_TEMP >= 150.0)
                   AND (ST290_ADH_TEMP <= 190.0) AND EMG_OK AND AIR_OK;
ST290_RB_START := xStart AND EMG_OK AND AIR_OK;
ST290_CAM_TRIG := xTrig;
ST290_LID_PLACE := xLid AND (ST290_CAM_LEN >= 620.0)
                   AND (ST290_CAM_LEN <= 660.0) AND NOT xStopp;
ST290_CLP_CLOSE := xSpann AND EMG_OK AND AIR_OK;
ST290_STA_STOP := xStopp;
END_PROGRAM

